// Asserts that the Dart port reproduces the website's own results for the sample data.
// Expected values come from test/fixtures/web_parity.json, generated by tool/export_fixtures.mjs
// from the website's selectors and parser (not hand-typed).
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:tsumugi_mobile/core/data/models.dart';
import 'package:tsumugi_mobile/core/data/selectors.dart';
import 'package:tsumugi_mobile/core/quickadd/parse.dart';

Map<String, dynamic> _json(String path) =>
    jsonDecode(File(path).readAsStringSync()) as Map<String, dynamic>;

void main() {
  final fixtures = Fixtures.fromJson(_json('assets/data/fixtures.json'));
  final d = fixtures.data;
  final web = _json('test/fixtures/web_parity.json');

  List<String> ids<T>(Iterable<T> list, String Function(T) id) => [
    for (final i in list) id(i),
  ];
  Map<String, dynamic> m(String key) => web[key] as Map<String, dynamic>;
  List<String> l(Object? v) => [for (final e in v as List) e as String];

  test('entity counts match the website (6 / 9 / 15 / 9 / 18 / 9)', () {
    final c = m('counts');
    expect(d.projects.length, c['projects']);
    expect(d.milestones.length, c['milestones']);
    expect(d.tasks.length, c['tasks']);
    expect(d.requirements.length, c['requirements']);
    expect(d.files.length, c['files']);
    expect(d.changes.length, c['changes']);
    expect(fixtures.templates.length, 5);
  });

  test('figures, today list and up next', () {
    final f = d.figures();
    final wf = m('figures');
    expect(
      (f.dueToday, f.overdue, f.doing),
      (wf['dueToday'], wf['overdue'], wf['doing']),
    );

    final t = d.todayList();
    final wt = m('todayList');
    expect(ids(t.overdue, (x) => x.id), l(wt['overdue']));
    expect(ids(t.today, (x) => x.id), l(wt['today']));
    expect(ids(t.doing, (x) => x.id), l(wt['doing']));
    expect(ids(t.doneToday, (x) => x.id), l(wt['doneToday']));

    final g = d.todayList('project-garden');
    final wg = m('todayListGarden');
    expect(ids(g.overdue, (x) => x.id), l(wg['overdue']));
    expect(ids(g.doing, (x) => x.id), l(wg['doing']));

    String tag(UpNextItem i) => '${i.isTask ? 'task' : 'milestone'}:${i.id}';
    expect([for (final i in d.upNext(7)) tag(i)], l(web['upNext7']));
    expect([for (final i in d.upNext(30)) tag(i)], l(web['upNext30']));
  });

  test('recent projects and recents', () {
    expect(ids(d.recentProjects(4), (p) => p.id), l(web['recentProjects']));
    expect([
      for (final r in d.recents(6)) '${r.type}:${r.id}',
    ], l(web['recents']));
    expect(ids(d.activeProjects, (p) => p.id), l(web['activeProjects']));
  });

  test('project progress, health, counts and next milestone', () {
    for (final p in d.projects) {
      final pr = d.projectProgress(p.id);
      final wp = m('projectProgress')[p.id] as Map<String, dynamic>;
      expect(
        (pr.done, pr.total, pr.pct),
        (wp['done'], wp['total'], wp['pct']),
        reason: p.id,
      );
      expect(d.projectHealth(p.id), m('projectHealth')[p.id], reason: p.id);
      final c = d.projectCounts(p.id);
      final wc = m('projectCounts')[p.id] as Map<String, dynamic>;
      expect(
        (c.tasks, c.milestones, c.requirements, c.files, c.changes),
        (
          wc['tasks'],
          wc['milestones'],
          wc['requirements'],
          wc['files'],
          wc['changes'],
        ),
        reason: p.id,
      );
      expect(d.nextMilestone(p.id)?.id, m('nextMilestone')[p.id], reason: p.id);
    }
  });

  test('milestone state and progress', () {
    for (final ms in d.milestones) {
      expect(milestoneState(ms), m('milestoneState')[ms.id], reason: ms.id);
      final p = d.milestoneProgress(ms.id);
      final wp = m('milestoneProgress')[ms.id] as Map<String, dynamic>;
      expect((p.done, p.total), (wp['done'], wp['total']), reason: ms.id);
    }
  });

  test('coverage, requirement links and criteria', () {
    final c = d.coverage();
    final wc = m('coverageAll');
    expect(
      (c.total, c.complete, c.withGaps),
      (wc['total'], wc['complete'], wc['withGaps']),
    );
    for (final p in d.projects) {
      final pc = d.coverage(p.id);
      final wpc = m('coverageByProject')[p.id] as Map<String, dynamic>;
      expect(
        (pc.total, pc.complete, pc.withGaps),
        (wpc['total'], wpc['complete'], wpc['withGaps']),
        reason: p.id,
      );
    }
    for (final r in d.requirements) {
      final links = d.requirementLinks(r);
      final w = m('requirementGaps')[r.id] as Map<String, dynamic>;
      final gaps = w['gaps'] as Map<String, dynamic>;
      expect(
        (links.gapTask, links.gapFile),
        (gaps['task'], gaps['file']),
        reason: r.id,
      );
      expect(ids(links.tasks, (x) => x.id), l(w['tasks']), reason: r.id);
      expect(ids(links.files, (x) => x.id), l(w['files']), reason: r.id);
      expect(ids(links.changes, (x) => x.id), l(w['changes']), reason: r.id);
      expect(links.milestone?.id, w['milestone'], reason: r.id);
      final cp = criteriaProgress(r);
      final wcp = m('criteria')[r.id] as Map<String, dynamic>;
      expect((cp.met, cp.total), (wcp['met'], wcp['total']), reason: r.id);
    }
  });

  test('overdue records and final-file flag', () {
    expect([
      for (final o in d.overdueRecords()) '${o.type}:${o.id}',
    ], l(web['overdue']));
    for (final f in d.files) {
      expect(isFinalFile(f), m('isFinalFile')[f.id], reason: f.id);
    }
  });

  test('record links match the website routes', () {
    final h = m('recordHref');
    expect(d.recordHref('Project', 'project-garden'), h['project']);
    expect(d.recordHref('Task', 't1'), h['task']);
    expect(d.recordHref('File', 'd-brief'), h['docFile']);
    expect(d.recordHref('File', 'a-cover'), h['plainFile']);
    expect(d.recordHref('Requirement', 'REQ-001'), h['requirement']);
    expect(d.recordHref('Milestone', 'm1'), h['milestone']);
    expect(d.recordHref('Change', 'r1'), h['change']);
  });

  test('quick add parser matches the website for every sample line', () {
    for (final c in web['parse'] as List) {
      final text = c['text'] as String;
      final expected = c['result'] as Map<String, dynamic>;
      final r = parseQuickAdd(text, c['fallback'] as String, d);
      expect(
        (r.title, r.priority, r.due, r.projectId),
        (
          expected['title'],
          expected['priority'],
          expected['due'],
          expected['projectId'],
        ),
        reason: '"$text"',
      );
    }
  });
}
